package com.kagof.runelite.plugins.brimhavenagility;

import com.google.common.annotations.VisibleForTesting;
import com.kagof.runelite.plugins.brimhavenagility.model.BrimhavenAgilityArenaLocation;
import com.kagof.runelite.plugins.brimhavenagility.model.BrimhavenAgilityArenaPath;
import javax.inject.Inject;
import net.runelite.client.Notifier;
import net.runelite.client.config.Notification;

public class BrimhavenAgilityNotifier
{
	private static final int NOTIFICATION_MAX_LEN = 67;

	private final Notifier notifier;
	private volatile BrimhavenAgilityArenaLocation lastDispenserLocation = null;

	@Inject
	public BrimhavenAgilityNotifier(final Notifier notifier)
	{
		this.notifier = notifier;
	}

	public void maybeNotifyDispenserDistance(final BrimhavenAgilityArenaPath currentPath, final BrimhavenAgilityConfig config)
	{
		if (!config.nearbyDispenserNotification().isEnabled())
		{
			return;
		}
		if (currentPath == null || currentPath.distance() < 0)
		{
			return;
		}
		if (currentPath.end().equals(lastDispenserLocation))
		{
			return;
		}
		// Update the last dispenser location regardless of whether we notified for it.
		// This means that we won't notify when the player moves closer, only if the dispenser moves.
		lastDispenserLocation = currentPath.end();
		if (currentPath.distance() > config.nearbyDispenserDistance())
		{
			return;
		}
		notify(config.nearbyDispenserNotification(), buildDispenserDistanceNotifyString(currentPath.distance()));

	}

	public void clear()
	{
		lastDispenserLocation = null;
	}

	private void notify(final Notification notification, final String message)
	{
		notifier.notify(notification, message);
	}

	@VisibleForTesting
	static String buildDispenserDistanceNotifyString(final int dispenserDistance)
	{
		StringBuilder sb = new StringBuilder(NOTIFICATION_MAX_LEN);
		sb.append("Brimhaven Agility: active ticket dispenser is ");
		if (dispenserDistance == 0)
		{
			sb.append("on your platform");
		}
		else
		{
			sb.append(dispenserDistance)
				.append(" platform hop");
			if (dispenserDistance > 1)
			{
				sb.append("s");
			}
			sb.append(" away");
		}
		return sb.toString();
	}
}

package com.kagof.runelite.plugins.brimhavenagility;

import com.google.common.collect.Lists;
import com.kagof.runelite.plugins.brimhavenagility.model.BrimhavenAgilityArenaLocation;
import com.kagof.runelite.plugins.brimhavenagility.model.BrimhavenAgilityArenaNeighbour;
import com.kagof.runelite.plugins.brimhavenagility.model.BrimhavenAgilityArenaPath;
import com.kagof.runelite.plugins.brimhavenagility.model.MapWithDefault;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;

/**
 * Uses the A* path finding algorithm to find the shortest (weighted) path from the player's current location, to the
 * target dispenser. Adapted from <a href="https://en.wikipedia.org/wiki/A*_search_algorithm#Pseudocode">Wikipedia's
 * pseudocode</a> implementation.
 */
@Slf4j
public final class BrimhavenAgilityPathFinder
{
	//belts & braces to ensure we never have an infinite loop

	private static final int MAX_VISITED_NODES = 25;

	// There are 25 nodes in the arena, each with at most 4 neighbours; we should never exceed this number
	private static final int MAX_TOTAL_NEIGHBOURS = 100;

	// not MAX_INT to avoid overflows
	public static final int NEVER_USE_WEIGHT = 999999;

	// lower than the NEVER_USER_WEIGHT so a valid path can still be found if too many obstacles are avoided
	public static final int AVOID_WEIGHT = 999;

	private BrimhavenAgilityPathFinder()
	{
	}

	public static BrimhavenAgilityArenaPath findPath(final WorldPoint playerLocation,
													 final WorldPoint dispenserLocation,
													 final int playerAgilityLevel,
													 final BrimhavenAgilityConfig config)
	{
		final BrimhavenAgilityArenaLocation start = BrimhavenAgilityArenaLocation.fromWorldPoint(playerLocation);
		final BrimhavenAgilityArenaLocation end = BrimhavenAgilityArenaLocation.fromWorldPoint(dispenserLocation);

		if (start == null || end == null)
		{
			return null;
		}

		Map<BrimhavenAgilityArenaLocation, Integer> gScore = new MapWithDefault<>(999999);
		gScore.put(start, 0);

		Map<BrimhavenAgilityArenaLocation, Integer> fScore = new MapWithDefault<>(999999);
		fScore.put(start, 0);

		PriorityQueue<BrimhavenAgilityArenaLocation> openSet = new PriorityQueue<>(Comparator.comparing(fScore::get));
		openSet.add(start);

		Map<BrimhavenAgilityArenaLocation, BrimhavenAgilityArenaLocation> cameFrom = new HashMap<>();

		int numVisitedNodes = 0;
		int totalNeighboursExamined = 0;
		while (!openSet.isEmpty())
		{
			final BrimhavenAgilityArenaLocation current = openSet.poll();
			numVisitedNodes++;
			if (current.equals(end))
			{
				return reconstructPath(cameFrom, current);
			}
			if (numVisitedNodes > MAX_VISITED_NODES)
			{
				log.warn("exceeded maximum number of nodes {}. This indicates a potential infinite loop", MAX_VISITED_NODES);
				return null;
			}

			openSet.remove(current);
			for (BrimhavenAgilityArenaNeighbour neighbour : BrimhavenAgilityArenaNeighbourDigest.getNeighbours(current))
			{
				totalNeighboursExamined++;
				if (totalNeighboursExamined > MAX_TOTAL_NEIGHBOURS)
				{
					log.warn("exceeded maximum number of neighbours examined {}. This indicates a potential infinite loop", MAX_TOTAL_NEIGHBOURS);
					return null;
				}
				if (neighbour.getLocation().equals(current))
				{
					log.warn("node {} marked as neighbour of itself", current);
					continue;
				}
				int tentativeGScore = gScore.get(current) + weightedDistance(neighbour, playerAgilityLevel, config);
				if (tentativeGScore < gScore.get(neighbour.getLocation()))
				{
					cameFrom.put(neighbour.getLocation(), current);
					gScore.put(neighbour.getLocation(), tentativeGScore);
					fScore.put(neighbour.getLocation(), tentativeGScore + heuristic(start, neighbour.getLocation()));
					if (!openSet.contains(neighbour.getLocation()))
					{
						openSet.add(neighbour.getLocation());
					}
				}
			}
		}
		return null;
	}

	private static int weightedDistance(BrimhavenAgilityArenaNeighbour neighbour, int agilityLevel, BrimhavenAgilityConfig config)
	{
		if (neighbour.getObstacle().getMinLevel() > agilityLevel)
		{
			return NEVER_USE_WEIGHT;
		}
		if (neighbour.getObstacle().getAvoidFunction().apply(config))
		{
			return AVOID_WEIGHT;
		}

		return neighbour.getObstacle().getWeight();
	}

	private static BrimhavenAgilityArenaPath reconstructPath(final Map<BrimhavenAgilityArenaLocation, BrimhavenAgilityArenaLocation> cameFrom, final BrimhavenAgilityArenaLocation end)
	{
		List<BrimhavenAgilityArenaLocation> path = new ArrayList<>();
		path.add(end);
		BrimhavenAgilityArenaLocation current = end;
		while (cameFrom.containsKey(current) && path.size() < MAX_VISITED_NODES)
		{
			current = cameFrom.get(current);
			path.add(current);
		}
		return new BrimhavenAgilityArenaPath(List.copyOf(Lists.reverse(path)));
	}

	/**
	 * The heuristic is the taxicab distance as the player can only move between platforms in this way.
	 */
	private static int heuristic(final BrimhavenAgilityArenaLocation start, final BrimhavenAgilityArenaLocation end)
	{
		return Math.abs(end.getX() - start.getX()) + Math.abs(end.getY() - start.getY());
	}
}

package com.kagof.runelite.plugins.brimhavenagility;

import com.kagof.runelite.plugins.brimhavenagility.model.BrimhavenAgilityArenaLocation;
import com.kagof.runelite.plugins.brimhavenagility.model.BrimhavenAgilityPlankChoice;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GroundObject;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ObjectID;

@Slf4j
@Singleton
public class BrimhavenAgilityPlankManager
{
	private static final Set<Integer> BAD = Set.of(ObjectID.AGILITYARENA_PLANK_BROKE1);
	private static final Set<Integer> GOOD = Set.of(
		ObjectID.AGILITYARENA_PLANK,
		ObjectID.AGILITYARENA_PLANK2,
		ObjectID.AGILITYARENA_PLANK3,
		ObjectID.AGILITYARENA_PLANK_MIDDLE,
		ObjectID.AGILITYARENA_PLANK2_MIDDLE,
		ObjectID.AGILITYARENA_PLANK3_MIDDLE);

	private static final int PLANE = BrimhavenAgilityArenaLocation.PLANE;

	private static final WorldArea PLANKS1_AREA = new WorldArea(2764, 9556, 6, 3, PLANE);
	private static final WorldArea PLANKS2_AREA = new WorldArea(2797, 9589, 6, 3, PLANE);

	@Getter
	private final GroundObject[][] planks1 = new GroundObject[3][6];
	@Getter
	private final GroundObject[][] planks2 = new GroundObject[3][6];
	private volatile boolean planks1Changed = false;
	private volatile boolean planks2Changed = false;

	@Getter
	private BrimhavenAgilityPlankChoice planks1Choice = BrimhavenAgilityPlankChoice.UNKNOWN;
	@Getter
	private BrimhavenAgilityPlankChoice planks2Choice = BrimhavenAgilityPlankChoice.UNKNOWN;

	@Inject
	public BrimhavenAgilityPlankManager()
	{
	}

	public void clear()
	{
		for (int y = 0; y < planks1.length; y++)
		{
			for (int x = 0; x < planks1[y].length; x++)
			{
				planks1[y][x] = null;
				planks2[y][x] = null;
			}
		}
		planks1Choice = BrimhavenAgilityPlankChoice.UNKNOWN;
		planks1Changed = false;
		planks2Choice = BrimhavenAgilityPlankChoice.UNKNOWN;
		planks2Changed = false;
	}

	public void recomputeCorrectPlanks()
	{
		if (planks1Changed)
		{
			planks1Choice = findCorrectPlank(planks1);
			planks1Changed = false;
			log.debug("planks1Choice recomputed as {}", planks1Choice);
		}
		if (planks2Changed)
		{
			planks2Choice = findCorrectPlank(planks2);
			planks2Changed = false;
			log.debug("planks2Choice recomputed as {}", planks2Choice);
		}
	}

	public boolean add(final GroundObject groundObject)
	{
		return updateVal(groundObject, groundObject);
	}

	public boolean remove(final GroundObject groundObject)
	{
		return updateVal(groundObject, null);
	}

	public boolean isOnBadPlank(final WorldPoint point)
	{
		if (point.isInArea(PLANKS1_AREA))
		{
			if (planks1Choice == BrimhavenAgilityPlankChoice.UNKNOWN)
			{
				return false;
			}
			return point.getY() - PLANKS1_AREA.getY() != planks1Choice.ordinal();
		}
		else if (point.isInArea(PLANKS2_AREA))
		{
			if (planks2Choice == BrimhavenAgilityPlankChoice.UNKNOWN)
			{
				return false;
			}
			return point.getY() - PLANKS2_AREA.getY() != planks2Choice.ordinal();
		}
		else
		{
			return false;
		}
	}

	private BrimhavenAgilityPlankChoice findCorrectPlank(final GroundObject[][] planks)
	{
		for (int y = 0; y < planks.length; y++)
		{
			boolean hasBad = false;
			for (int x = 0; x < planks[y].length; x++)
			{
				if (planks[y][x] == null)
				{
					return BrimhavenAgilityPlankChoice.UNKNOWN;
				}
				if (BAD.contains(planks[y][x].getId()))
				{
					hasBad = true;
					break;
				}
			}
			if (!hasBad)
			{
				if (y > BrimhavenAgilityPlankChoice.values().length)
				{
					log.warn("y value {} greater than number of options; this should not happen", y);
					break;
				}
				return BrimhavenAgilityPlankChoice.values()[y];
			}
		}
		return BrimhavenAgilityPlankChoice.UNKNOWN;
	}

	private boolean updateVal(final GroundObject compareTo, final GroundObject setTo)
	{
		if (compareTo.getPlane() != PLANE)
		{
			return false;
		}
		if (!GOOD.contains(compareTo.getId()) && !BAD.contains(compareTo.getId()))
		{
			return false;
		}
		synchronized (planks1)
		{
			if (compareTo.getWorldLocation().isInArea(PLANKS1_AREA))
			{
				int y = compareTo.getWorldLocation().getY() - PLANKS1_AREA.getY();
				int x = compareTo.getWorldLocation().getX() - PLANKS1_AREA.getX();
				if (y > planks1.length)
				{
					log.warn("y value {} higher than planks1 length; this should not happen", y);
					return false;
				}
				if (x > planks1[y].length)
				{
					log.warn("x value {} higher than planks1[{}] length; this should not happen", x, y);
					return false;
				}
				planks1[y][x] = setTo;
				planks1Changed = true;
				return true;
			}
		}
		synchronized (planks2)
		{
			if (compareTo.getWorldLocation().isInArea(PLANKS2_AREA))
			{
				int y = compareTo.getWorldLocation().getY() - PLANKS2_AREA.getY();
				int x = compareTo.getWorldLocation().getX() - PLANKS2_AREA.getX();
				if (y > planks2.length)
				{
					log.warn("y value {} higher than planks2 length; this should not happen", y);
					return false;
				}
				if (x > planks2[y].length)
				{
					log.warn("x value {} higher than planks2[{}] length; this should not happen", x, y);
					return false;
				}
				planks2[y][x] = setTo;
				planks2Changed = true;
				return true;
			}
		}
		return false;
	}
}

package com.kagof.runelite.plugins.brimhavenagility;

import com.google.inject.Provides;
import com.kagof.runelite.plugins.brimhavenagility.model.BrimhavenAgilityArenaPath;
import com.kagof.runelite.plugins.brimhavenagility.overlay.BrimhavenAgilityOverlay;
import com.kagof.runelite.plugins.brimhavenagility.overlay.BrimhavenAgilityPanelOverlay;
import com.kagof.runelite.plugins.brimhavenagility.overlay.BrimhavenAgilityPlankOverlay;
import com.kagof.runelite.plugins.brimhavenagility.overlay.BrimhavenAgilityShopOverlay;
import java.awt.Color;
import javax.inject.Inject;
import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.Skill;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GroundObjectDespawned;
import net.runelite.api.events.GroundObjectSpawned;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.kit.KitType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Brimhaven Agility"
)
public class BrimhavenAgilityPlugin extends Plugin
{

	private static final int ENTRY_PAID_VARBIT = VarbitID.AGILITYARENA_CANENTER;
	private static final int COOLDOWN_REQUIRED_VARBIT = VarbitID.AGILITY_ARENA_TELEPORTED_OUT;
	private static final int TICKET_AVAILABLE_VARBIT = VarbitID.AGILITYARENA_TICKETAVAILABLE;
	private static final int KARAMJA_EASY_VARBIT = VarbitID.KARAMJA_EASY_COUNT;
	private static final int KARAMJA_MEDIUM_VARBIT = VarbitID.KARAMJA_MED_COUNT;
	private static final int FOLLOWER_NPC = VarPlayerID.FOLLOWER_NPC;

	private static final int KARAMJA_EASY_TASKS = 10;
	private static final int KARAMJA_MEDIUM_TASKS = 19;

	private static final int KARAMJA_GLOVES_2 = ItemID.ATJUN_GLOVES_MED;
	private static final int KARAMJA_GLOVES_3 = ItemID.ATJUN_GLOVES_HARD;
	private static final int KARAMJA_GLOVES_4 = ItemID.ATJUN_GLOVES_ELITE;

	private static final WorldArea ARENA_ENTRY_AREA = new WorldArea(2805, 3185, 7, 11, 0);

	public static final int AGILITY_ARENA_REGION_ID = 11157;

	@Getter
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private BrimhavenAgilityOverlay overlay;

	@Inject
	private BrimhavenAgilityPanelOverlay panelOverlay;

	@Inject
	private BrimhavenAgilityPlankOverlay plankOverlay;

	@Inject
	private BrimhavenAgilityShopOverlay shopOverlay;

	@Inject
	private BrimhavenAgilityConfig config;

	@Inject
	@Getter
	private BrimhavenAgilityPlankManager plankManager;

	@Inject
	private BrimhavenAgilityNotifier notifier;

	@Getter
	private volatile int agilityLevel;
	@Getter
	private volatile BrimhavenAgilityArenaPath currentPath;
	@Getter
	private volatile boolean ticketAvailable;
	@Getter
	private volatile boolean entryPaid;
	@Getter
	private volatile boolean cooldownPassed;
	private volatile int easyTasksCompleted;
	private volatile int mediumTasksCompleted;
	@Getter
	private volatile boolean hasNoFollower;

	@Getter
	@Setter
	private volatile boolean shopOpen;

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(overlay);
		overlayManager.add(panelOverlay);
		overlayManager.add(plankOverlay);
		overlayManager.add(shopOverlay);
		notifier.clear();
		agilityLevel = client.getBoostedSkillLevel(Skill.AGILITY);
		currentPath = null;
		clientThread.invokeLater(() -> {
			ticketAvailable = client.getVarbitValue(TICKET_AVAILABLE_VARBIT) > 0;
			entryPaid = client.getVarbitValue(ENTRY_PAID_VARBIT) > 0;
			cooldownPassed = client.getVarbitValue(COOLDOWN_REQUIRED_VARBIT) == 0;
			easyTasksCompleted = client.getVarbitValue(KARAMJA_EASY_VARBIT);
			mediumTasksCompleted = client.getVarbitValue(KARAMJA_MEDIUM_VARBIT);
			hasNoFollower = client.getVarpValue(FOLLOWER_NPC) == -1;
		});
		shopOpen = false;
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(overlay);
		overlayManager.remove(panelOverlay);
		overlayManager.remove(plankOverlay);
		overlayManager.remove(shopOverlay);
		BrimhavenAgilityArenaNeighbourDigest.unload();
		plankManager.clear();
		notifier.clear();
		agilityLevel = 0;
		currentPath = null;
		ticketAvailable = true;
		easyTasksCompleted = 0;
		mediumTasksCompleted = 0;
		hasNoFollower = true;
		shopOpen = false;
	}

	@Subscribe
	public void onWidgetLoaded(final WidgetLoaded loaded)
	{
		if (loaded.getGroupId() == InterfaceID.OMNISHOP_MAIN && isNearAgilityArenaEntrance())
		{
			shopOpen = true;
		}
	}


	@Subscribe
	public void onWidgetClosed(final WidgetClosed closed)
	{
		if (shopOpen && closed.getGroupId() == InterfaceID.OMNISHOP_MAIN)
		{
			shopOpen = false;
		}
	}

	@Subscribe
	public void onGameTick(final GameTick tick)
	{
		recompute();
	}

	@Subscribe
	public void onVarbitChanged(final VarbitChanged event)
	{
		switch (event.getVarbitId())
		{
			case ENTRY_PAID_VARBIT:
				entryPaid = event.getValue() > 0;
				break;
			case COOLDOWN_REQUIRED_VARBIT:
				cooldownPassed = event.getValue() == 0;
				break;
			case TICKET_AVAILABLE_VARBIT:
				ticketAvailable = event.getValue() > 0;
				if (isInAgilityArena() && !ticketAvailable && config.removeArrowWhenClaimed() && client.hasHintArrow())
				{
					client.clearHintArrow();
				}
				break;
			case KARAMJA_EASY_VARBIT:
				easyTasksCompleted = event.getValue();
				break;
			case KARAMJA_MEDIUM_VARBIT:
				mediumTasksCompleted = event.getValue();
				break;
		}
		//noinspection SwitchStatementWithTooFewBranches
		switch (event.getVarpId())
		{
			case FOLLOWER_NPC:
				hasNoFollower = event.getValue() == -1;
				break;
		}
	}

	@Subscribe
	public void onGroundObjectSpawned(final GroundObjectSpawned event)
	{
		if (AGILITY_ARENA_REGION_ID == event.getGroundObject().getWorldLocation().getRegionID())
		{
			plankManager.add(event.getGroundObject());
		}
	}

	@Subscribe
	public void onGroundObjectDespawned(final GroundObjectDespawned event)
	{
		if (AGILITY_ARENA_REGION_ID == event.getGroundObject().getWorldLocation().getRegionID())
		{
			plankManager.remove(event.getGroundObject());
		}
	}

	@Subscribe
	public void onMenuEntryAdded(final MenuEntryAdded event)
	{
		if (config.highlightPlankMenuOptions() && isInAgilityArena())
		{
			if (MenuAction.of(event.getType()) == MenuAction.GAME_OBJECT_FIRST_OPTION
				&& event.getOption().equals("Walk-on")
				&& event.getTarget().contains("Plank"))
			{
				recolourPlankMenuOption(event);
			}
		}

		if (config.showGloveWarning() && shopOpen && !isWearingKaramjaGloves234())
		{
			if (BrimhavenAgilityShopHandler.isAgilityXPBuyButtonMenuOption(event, client))
			{
				event.getMenuEntry().setType(MenuAction.CC_OP_LOW_PRIORITY);
				event.getMenuEntry().setDeprioritized(true);
				event.getMenuEntry().setOption(ColorUtil.wrapWithColorTag(event.getMenuEntry().getOption(), Color.RED));
			}
			else if (BrimhavenAgilityShopHandler.isAgilityXPListBuyOrSelectMenuOption(event))
			{
				event.getMenuEntry().setType(MenuAction.CC_OP_LOW_PRIORITY);
				event.getMenuEntry().setDeprioritized(true);
				event.getMenuEntry().setTarget(ColorUtil.wrapWithColorTag("Agility XP", Color.RED));
			}
		}

	}

	private void recompute()
	{
		recomputePlanksIfNeeded();
		boolean pathChanged = recomputePathIfNeeded();
		if (pathChanged)
		{
			notifier.maybeNotifyDispenserDistance(currentPath, config);
		}
	}

	private void recomputePlanksIfNeeded()
	{
		if (isInAgilityArena() &&
			(config.highlightCorrectPlank() || config.highlightPlankMenuOptions() || config.adjustPathForPlanks()))
		{
			plankManager.recomputeCorrectPlanks();
		}
	}

	private boolean recomputePathIfNeeded()
	{
		boolean changed = false;
		boolean inAgilityArena = isInAgilityArena();
		if (inAgilityArena && ticketAvailable)
		{
			WorldPoint ticketPosition = client.getHintArrowPoint();
			WorldPoint playerLocation = client.getLocalPlayer().getWorldLocation();
			if (currentPath != null)
			{
				if (currentPath.hasPathChanged(playerLocation, ticketPosition))
				{
					log.debug("current path changed, calculating subpath if possible");
					// see if we can use a sub-path
					currentPath = currentPath.subPath(playerLocation, ticketPosition);
					log.debug("subpath calculated as {}", currentPath);
					changed = true;
				}
			}
			if (currentPath == null)
			{
				log.debug("current path null, calculating new path");
				currentPath = BrimhavenAgilityPathFinder.findPath(playerLocation, ticketPosition, agilityLevel, config);
				changed = true;
			}
		}
		else if (currentPath != null) // not in the arena or ticket not available & current path is non-null
		{
			currentPath = null;
			if (!inAgilityArena)
			{
				ticketAvailable = true;
			}
			changed = true;
		}
		if (changed)
		{
			log.debug("New Brimhaven Agility Arena path: {}", currentPath);
		}
		return changed;
	}

	@Subscribe
	public void onConfigChanged(final ConfigChanged configChanged)
	{
		if (configChanged.getGroup().equals("brimhavenagility"))
		{
			currentPath = null;
			clientThread.invokeLater(this::recompute);
		}
	}

	@Subscribe
	public void onStatChanged(final StatChanged statChanged)
	{
		if (statChanged.getSkill() == Skill.AGILITY && agilityLevel != statChanged.getBoostedLevel())
		{
			agilityLevel = statChanged.getBoostedLevel();
			currentPath = null;
			recomputePathIfNeeded();
		}
	}

	@Provides
	BrimhavenAgilityConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BrimhavenAgilityConfig.class);
	}

	public boolean isNearAgilityArenaEntrance()
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return false;
		}
		WorldPoint location = local.getWorldLocation();
		if (location == null)
		{
			return false;
		}
		return location.isInArea(ARENA_ENTRY_AREA);
	}


	public boolean isInAgilityArena()
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return false;
		}

		WorldPoint location = local.getWorldLocation();
		if (location == null)
		{
			return false;
		}
		return location.getRegionID() == AGILITY_ARENA_REGION_ID;
	}

	public boolean isWearingKaramjaGloves234()
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return false;
		}
		PlayerComposition comp = local.getPlayerComposition();
		if (comp == null)
		{
			return false;
		}
		int gloveSlot = comp.getEquipmentId(KitType.HANDS);
		return gloveSlot == KARAMJA_GLOVES_2 || gloveSlot == KARAMJA_GLOVES_3 || gloveSlot == KARAMJA_GLOVES_4;
	}

	public boolean isMediumDiaryCompleted()
	{
		return easyTasksCompleted == KARAMJA_EASY_TASKS && mediumTasksCompleted == KARAMJA_MEDIUM_TASKS;
	}

	private void recolourPlankMenuOption(final MenuEntryAdded event)
	{
		final WorldView wv = client.getWorldView(event.getMenuEntry().getWorldViewId());
		final WorldPoint point = WorldPoint.fromScene(wv, event.getActionParam0(), event.getActionParam1(), wv.getPlane());
		event.getMenuEntry().setTarget(ColorUtil.wrapWithColorTag(Text.removeTags(event.getTarget()),
			plankManager.isOnBadPlank(point) ? config.incorrectPlankColour() : config.correctPlankColour()));
	}
}

package com.kagof.runelite.plugins.brimhavenagility;

import java.awt.Rectangle;
import net.runelite.api.Client;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

public class BrimhavenAgilityShopHandler
{
	public static final int FRAME_ID = InterfaceID.OmnishopMain.FRAME;
	public static final int LIST_ID = InterfaceID.OmnishopMain.LIST;
	public static final int INFO_ID = InterfaceID.OmnishopMain.INFO;
	public static final int BUY_BUTTONS_ID = InterfaceID.OmnishopMain.BUTTONS_INFO;

	public static Widget getFrame(final Client client)
	{
		return client.getWidget(FRAME_ID);
	}

	public static Widget getList(final Client client)
	{
		return client.getWidget(LIST_ID);
	}

	public static Widget getInfo(final Client client)
	{
		return client.getWidget(INFO_ID);
	}

	public static Widget getBuyButtons(final Client client)
	{
		return client.getWidget(BUY_BUTTONS_ID);
	}

	public static boolean shopNameMatches(final Client client)
	{
		final Widget frame = getFrame(client);
		if (frame == null)
		{
			return false;
		}
		final Widget[] frameChildren = frame.getChildren();
		if (frameChildren == null)
		{
			return false;
		}
		for (var frameChild : frameChildren)
		{
			if (frameChild.getText() != null && frameChild.getText().contains("Agility Arena Store"))
			{
				return true;
			}
		}
		return false;
	}

	public static boolean isAgilityXPOptionSelected(final Widget info)
	{
		if (info == null)
		{
			return false;
		}
		var infoChildren = info.getChildren();
		if (infoChildren == null)
		{
			return false;
		}
		for (var infoChild : infoChildren)
		{
			if (infoChild.getText() != null && infoChild.getText().contains("Agility XP"))
			{
				return true;
			}
		}
		return false;
	}

	public static Rectangle agilityXPBuyButtonBounds(final Client client)
	{
		final Widget info = getInfo(client);
		final Widget buyButtons = getBuyButtons(client);
		if (info == null || buyButtons == null)
		{
			return null;
		}
		Rectangle buyButtonBounds = buyButtons.getBounds();
		if (buyButtonBounds.x < 0 || buyButtonBounds.y < 0)
		{
			return null;
		}
		if (isAgilityXPOptionSelected(info))
		{
			return buyButtonBounds;
		}
		return null;
	}

	public static Rectangle getAgilityXPListItemBounds(final Client client)
	{
		final Widget list = getList(client);
		if (list == null)
		{
			return null;
		}
		var listChildren = list.getChildren();
		if (listChildren == null)
		{
			return null;
		}
		for (var listChild : listChildren)
		{
			if (listChild.getName() != null && listChild.getName().contains("Agility XP"))
			{
				Rectangle bounds = listChild.getBounds();
				if (bounds != null && (bounds.x == -1 || bounds.y == -1))
				{
					return null;
				}
				return bounds;
			}
		}
		return null;
	}

	public static boolean isAgilityXPBuyButtonMenuOption(final MenuEntryAdded event, final Client client)
	{
		return "".equals(event.getTarget())
			&& event.getOption().contains("Buy-")
			&& isAgilityXPOptionSelected(getInfo(client));
	}

	public static boolean isAgilityXPListBuyOrSelectMenuOption(final MenuEntryAdded event)
	{
		return event.getTarget().contains("Agility XP")
			&& ("Select".equals(event.getOption()) || event.getOption().contains("Buy-"));
	}
}

package com.kagof.runelite.plugins.brimhavenagility;

import com.kagof.runelite.plugins.brimhavenagility.model.BrimhavenAgilityArenaLocation;
import com.kagof.runelite.plugins.brimhavenagility.model.BrimhavenAgilityArenaPath;
import com.kagof.runelite.plugins.brimhavenagility.model.BrimhavenAgilityPlankChoice;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;

@Slf4j
@Singleton
public class BrimhavenAgilityWorldPathConverter
{
	private static final Set<Integer> PLANKS_1_X = Set.of(0, 1);
	private static final int PLANKS_1_Y = 1;
	private static final Set<Integer> PLANKS_2_X = Set.of(3, 4);
	private static final int PLANKS_2_Y = 4;

	private final BrimhavenAgilityPlankManager plankManager;
	private final BrimhavenAgilityConfig config;

	private int prevComputedHash = -1;
	private List<WorldPoint> prevComputedWorldPoints = null;

	@Inject
	public BrimhavenAgilityWorldPathConverter(final BrimhavenAgilityPlankManager plankManager, final BrimhavenAgilityConfig config)
	{
		this.plankManager = plankManager;
		this.config = config;
	}

	public synchronized List<WorldPoint> toWorldPoints(final BrimhavenAgilityArenaPath path)
	{
		// prevents us from unnecessarily performing this conversion over and over
		final int hash = Objects.hash(path,
			plankManager.getPlanks1Choice(),
			plankManager.getPlanks2Choice(),
			config.adjustPathForPlanks());
		if (hash == prevComputedHash && prevComputedWorldPoints != null)
		{
			return prevComputedWorldPoints;
		}

		log.debug("path, planks or config has changed; recomputing world points");
		prevComputedHash = hash;
		if (!config.adjustPathForPlanks() || path.getLocations().size() < 2)
		{
			prevComputedWorldPoints = path.getLocations().stream()
				.map(BrimhavenAgilityArenaLocation::toCenteredWorldPoint)
				.collect(Collectors.toList());
			return prevComputedWorldPoints;
		}

		prevComputedWorldPoints = new ArrayList<>();
		prevComputedWorldPoints.add(path.getLocations().get(0).toCenteredWorldPoint());
		for (int i = 1; i < path.getLocations().size(); i++)
		{
			final BrimhavenAgilityArenaLocation prev = path.getLocations().get(i - 1);
			final BrimhavenAgilityArenaLocation curr = path.getLocations().get(i);
			if (plankManager.getPlanks1Choice() != BrimhavenAgilityPlankChoice.UNKNOWN &&
				PLANKS_1_Y == prev.getY() && PLANKS_1_Y == curr.getY()
				&& PLANKS_1_X.contains(prev.getX()) && PLANKS_1_X.contains(curr.getX()))

			{
				addPlanksToWorldPoints(prevComputedWorldPoints, prev, curr, plankManager.getPlanks1Choice());
			}
			else if (plankManager.getPlanks2Choice() != BrimhavenAgilityPlankChoice.UNKNOWN &&
				PLANKS_2_Y == prev.getY() && PLANKS_2_Y == curr.getY()
				&& PLANKS_2_X.contains(prev.getX()) && PLANKS_2_X.contains(curr.getX()))
			{
				addPlanksToWorldPoints(prevComputedWorldPoints, prev, curr, plankManager.getPlanks2Choice());
			}
			prevComputedWorldPoints.add(curr.toCenteredWorldPoint());
		}
		return prevComputedWorldPoints;
	}

	private void addPlanksToWorldPoints(List<WorldPoint> out, BrimhavenAgilityArenaLocation prev, BrimhavenAgilityArenaLocation curr, BrimhavenAgilityPlankChoice planksChoice)
	{
		final boolean eastToWest = prev.getX() < curr.getX();
		final var point1 = prev.toCenteredWorldPoint()
			.dx((eastToWest ? 1 : -1) * 2);
		final var point2 = curr.toCenteredWorldPoint()
			.dx((eastToWest ? -1 : 1) * 2);
		out.add(point1);
		out.add(point1.dy(planksChoice.ordinal() - 1));
		out.add(point2.dy(planksChoice.ordinal() - 1));
		out.add(point2);
	}
}

package com.kagof.runelite.plugins.brimhavenagility.model;

import com.google.common.collect.ComparisonChain;
import com.kagof.runelite.plugins.brimhavenagility.BrimhavenAgilityPlugin;
import lombok.EqualsAndHashCode;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

/**
 * A location of a platform in the Agility Arena. Each platform is given an x & y coordinate from 0 to 4, starting from
 * the southwest corner. These points may be mapped to or from a {@link WorldPoint}.
 */
@Value
@EqualsAndHashCode
public class BrimhavenAgilityArenaLocation implements Comparable<BrimhavenAgilityArenaLocation>
{
	private static final int PLATFORM_CENTER_OFFSET = 5;
	private static final int PLATFORM_WIDTH = 11;
	private static final int PLATFORM_HEIGHT = 11;
	private static final int PLATFORM_START_X = 9;
	private static final int PLATFORM_START_Y = 10;
	public static final int PLANE = 3;

	int x;
	int y;

	/**
	 * @return the WorldPoint of the center of the platform.
	 */
	public WorldPoint toCenteredWorldPoint()
	{
		return WorldPoint.fromRegion(BrimhavenAgilityPlugin.AGILITY_ARENA_REGION_ID,
			PLATFORM_START_X + (x * PLATFORM_WIDTH),
			PLATFORM_START_Y + (y * PLATFORM_HEIGHT),
			3);
	}

	public static BrimhavenAgilityArenaLocation fromWorldPoint(WorldPoint worldPoint)
	{
		if (worldPoint == null)
		{
			return null;
		}
		if (worldPoint.getRegionID() != BrimhavenAgilityPlugin.AGILITY_ARENA_REGION_ID)
		{
			return null;
		}

		// adding the offset changes the origin from the center of the platform to the sw corner.
		// dividing by width/height rounds down to choose the correct platform.
		int x = (worldPoint.getRegionX() + PLATFORM_CENTER_OFFSET - PLATFORM_START_X) / PLATFORM_WIDTH;
		int y = (worldPoint.getRegionY() + PLATFORM_CENTER_OFFSET - PLATFORM_START_Y) / PLATFORM_HEIGHT;

		if (x < 0 || y < 0 || x > 4 || y > 4)
		{
			return null; // not on a platform
		}
		return new BrimhavenAgilityArenaLocation(x, y);
	}

	public static BrimhavenAgilityArenaLocation of(int x, int y)
	{
		return new BrimhavenAgilityArenaLocation(x, y);
	}

	@Override
	public String toString()
	{
		return "(" + x + ", " + y + ")";
	}

	@Override
	public int compareTo(BrimhavenAgilityArenaLocation o)
	{
		return ComparisonChain.start().compare(this.x, o.x).compare(this.y, o.y).result();
	}
}

